export function validateQuery(input={}){const limit=Math.max(1,Math.min(200,Number(input.limit)||50));let bbox=null;if(input.bbox){const xs=Array.isArray(input.bbox)?input.bbox:String(input.bbox).split(',').map(Number);if(xs.length!==4||xs.some(x=>!Number.isFinite(x))||xs[0]<-180||xs[2]>180||xs[1]<-90||xs[3]>90||xs[0]>=xs[2]||xs[1]>=xs[3])return{ok:false,reason:'INVALID_BBOX'};bbox=xs;}const from=input.from?Date.parse(input.from):null,to=input.to?Date.parse(input.to):null;if(from!==null&&!Number.isFinite(from)||to!==null&&!Number.isFinite(to))return{ok:false,reason:'INVALID_TIME'};if(Number.isFinite(from)&&Number.isFinite(to)&&from>to)return{ok:false,reason:'REVERSED_TIME'};return{ok:true,query:{limit,bbox,from:Number.isFinite(from)?new Date(from).toISOString():null,to:Number.isFinite(to)?new Date(to).toISOString():null}};}
